    def _active_client_name_exists(self, name: str, loan_type=None, exclude_client_uid: str | None = None) -> bool:
        """True if an active client already uses this exact visible name in the same loan type."""
        try:
            nm = " ".join(str(name or "").strip().split())
        except Exception:
            nm = str(name or "").strip()
        if not nm:
            return False
        try:
            lt = self._effective_lt(loan_type)
        except Exception:
            _lt_raw = str(loan_type or '').strip().lower().replace(' ', '')
            lt = '7x7' if _lt_raw in ('7x7', '7×7') else 'Regular'
        try:
            cur = self.conn.cursor()
            sql = (
                "SELECT 1 FROM clients "
                "WHERE UPPER(TRIM(name)) = UPPER(TRIM(?)) "
                "AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') "
                "AND IFNULL(is_archived,0)=0"
            )
            params = [nm, lt]
            ex = str(exclude_client_uid or "").strip()
            if ex:
                sql += " AND IFNULL(client_uid,'') <> ?"
                params.append(ex)
            sql += " LIMIT 1"
            return bool(cur.execute(sql, tuple(params)).fetchone())
        except Exception:
            return False

    def add_client(self, name, principal=0.0, date_released=None, area=None, interest_rate=None, new_until=None, loan_type=None, pay_start_offset_days=1, contact_number='', payment_term='Daily', payment_amount=0.0, payment_mode='Cash', due_weekday='', semi_due_day1=None, semi_due_day2=None, monthly_due_day=None, flex_due_rule=''):
        cur = self.conn.cursor()
        now = date.today().strftime("%Y-%m-%d")
        try:
            p = float(principal or 0)
        except Exception:
            p = 0.0
        try:
            rate = float(interest_rate) if interest_rate is not None else 0.20
            # treat 20 as 20% if user enters whole percent
            if rate > 1.0:
                rate = rate / 100.0
        except Exception:
            rate = 0.20

        # Normalize loan_type
        lt = (str(loan_type or '').strip() or '')
        if not lt:
            lt = '7x7' if '7X7' in (name or '').upper() else 'Regular'
        elif lt.lower().replace(' ', '') in ('7x7','7×7'):
            lt = '7x7'
        else:
            lt = 'Regular'

        # Prevent duplicate active client names only within the same loan type.
        try:
            _name_exact = " ".join(str(name or "").strip().split())
        except Exception:
            _name_exact = str(name or "").strip()
        if _name_exact and self._active_client_name_exists(_name_exact, loan_type=lt):
            return False

        # 7x7 is treated as no-interest
        if lt == '7x7':
            rate = 0.0
        intr = round(p * rate, 2)
        total = round(p + intr, 2)

        dr = date_released or now
        try:
            datetime.strptime(dr, "%Y-%m-%d")
        except Exception:
            dr = now
        due_days = 49 if lt == '7x7' else 120
        due = (datetime.strptime(dr, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")

        # Normalize new_until (optional)
        if new_until:
            try:
                datetime.strptime(str(new_until), "%Y-%m-%d")
            except Exception:
                new_until = None

        # Payment start offset: 0 = same day as release, 1 = next day after release
        try:
            psod = int(pay_start_offset_days or 0)
            psod = 1 if psod >= 1 else 0
        except Exception:
            psod = 0

        # Contact number (optional)
        try:
            cn = str(contact_number or '').strip()
        except Exception:
            cn = ''

        # Payment term & payment amount (optional)
        def _norm_term(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return 'Daily'
            s2 = s.lower().replace('-', '').replace('_', '').replace(' ', '')
            if s2.startswith('d'):
                return 'Daily'
            if 'week' in s2 or s2.startswith('w'):
                return 'Weekly'
            if 'semi' in s2 or 'bi' in s2 or 'quin' in s2:
                return 'Semi'
            if 'month' in s2 or s2.startswith('m'):
                return 'Monthly'
            # allow exact title-case values
            t = s.strip().title()
            return t if t in ('Daily','Weekly','Semi','Monthly') else 'Daily'

        pt = _norm_term(payment_term)
        try:
            pa = float(str(payment_amount).replace(',', '.').strip()) if payment_amount not in (None, '') else 0.0
        except Exception:
            pa = 0.0

        # Payment mode (optional)
        pm = _spina__merge_payment_mode(payment_mode)

        # Due schedule fields
        def _norm_weekday(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return ''
            key = s[:3].strip().lower()
            mp = {
                'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
                'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
            }
            return mp.get(key, '')

        def _norm_dom(v):
            try:
                if v in (None, ''):
                    return None
                n = int(str(v).strip())
                return n if 1 <= n <= 31 else None
            except Exception:
                return None

        dwd = _norm_weekday(due_weekday)
        sd1 = _norm_dom(semi_due_day1)
        sd2 = _norm_dom(semi_due_day2)
        mdd = _norm_dom(monthly_due_day)
        try:
            fdr = str(flex_due_rule or '').strip()
        except Exception:
            fdr = ''

        # Stable uid for history
        try:
            import uuid
            uid = uuid.uuid4().hex
        except Exception:
            uid = str(datetime.now().timestamp()).replace('.', '')

        try:
            # Ensure area exists in master list (best-effort)
            try:
                _a = (area or '').strip()
                if _a:
                    self.ensure_area_exists(_a)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0121', 'suppressed exception excpass_0121', __spina_exc)
                pass

            cur.execute(
                "INSERT INTO clients (client_uid, person_uid, link_opt_out, name, contact_number, principal, interest_rate, interest_amount, total_to_pay, date_released, due_date, created_at, area, new_until, pay_start_offset_days, loan_type, payment_term, payment_amount, payment_mode, due_weekday, semi_due_day1, semi_due_day2, monthly_due_day, flex_due_rule) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (uid, '', 0, name.strip(), cn, p, rate, intr, total, dr, due, now, (area or ''), new_until, psod, lt, pt, pa, pm, dwd, sd1, sd2, mdd, fdr)
            )
            self.conn.commit()
            try:
                from spina_app.area_hierarchy_ops import sync_client_area_uid_from_path
                sync_client_area_uid_from_path(self.conn, uid)
            except Exception as __spina_exc:
                _log_suppressed_once(
                    'area_uid_sync_add',
                    'suppressed client Area UID sync after add',
                    __spina_exc,
                )
                pass

            # Ensure renew defaults (safe if columns not present)
            try:
                cur.execute("UPDATE clients SET last_released_cash = COALESCE(last_released_cash, principal), renew_count = COALESCE(renew_count, 0) WHERE client_uid=?", (uid,))
                self.conn.commit()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0122', 'suppressed exception excpass_0122', __spina_exc)
                pass

            # Log history
            try:
                new_row = self.get_client_by_uid(uid) or self.get_client_info(name.strip(), loan_type=lt) or {}
                self._log_client_history(uid, 'ADD', old_row=None, new_row=new_row, source='clients:add')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0123', 'suppressed exception excpass_0123', __spina_exc)
                pass

            return True
        except sqlite3.IntegrityError:
            return False



    def update_client(self, old_name, new_name=None, principal=None, date_released=None, area=None, interest_rate=None, new_until=None, loan_type=None, pay_start_offset_days=None, contact_number=None, payment_term=None, payment_amount=None, payment_mode=None, due_weekday=None, semi_due_day1=None, semi_due_day2=None, monthly_due_day=None, flex_due_rule=None):
        """Update a client (append-only history is written to client_history)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)

        old_row = self.get_client_info(old_name, loan_type=lt) or {}
        if not old_row:
            return False
        uid = (old_row.get("client_uid") or "").strip()

        # Resolve new values (keep existing if None)
        name_new = (new_name or old_name or "").strip()
        if not name_new:
            name_new = (old_row.get("name") or old_name or "").strip()

        # Prevent duplicate active client names only within the same loan type.
        try:
            _name_exact = " ".join(str(name_new or "").strip().split())
        except Exception:
            _name_exact = str(name_new or "").strip()
        if _name_exact and self._active_client_name_exists(_name_exact, loan_type=lt, exclude_client_uid=uid):
            return False

        # Principal / interest
        try:
            p = float(principal) if principal is not None else float(old_row.get("principal") or 0.0)
        except Exception:
            p = 0.0
        try:
            r = float(interest_rate) if interest_rate is not None else float(old_row.get("interest_rate") or 0.20)
            if r > 1.0:
                r = r / 100.0
        except Exception:
            r = 0.20

        # 7x7 is treated as no-interest
        if lt == '7x7':
            r = 0.0

        intr = round(p * r, 2)
        total = round(p + intr, 2)

        # Dates
        dr = (date_released or old_row.get("date_released") or date.today().strftime("%Y-%m-%d"))
        try:
            datetime.strptime(dr, "%Y-%m-%d")
        except Exception:
            dr = old_row.get("date_released") or date.today().strftime("%Y-%m-%d")

        due_days = 49 if lt == '7x7' else 120
        due = (datetime.strptime(dr, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")

        # Area
        if area is None:
            area_val = old_row.get("area") or ""
        else:
            area_val = area
            try:
                _a = (area_val or '').strip()
                if _a:
                    self.ensure_area_exists(_a)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0124', 'suppressed exception excpass_0124', __spina_exc)
                pass

        # Contact number
        if contact_number is None:
            cn = old_row.get("contact_number") or ""
        else:
            try:
                cn = str(contact_number).strip()
            except Exception:
                cn = ""

        # Payment term & payment amount
        def _norm_term(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return 'Daily'
            s2 = s.lower().replace('-', '').replace('_', '').replace(' ', '')
            if s2.startswith('d'):
                return 'Daily'
            if 'week' in s2 or s2.startswith('w'):
                return 'Weekly'
            if 'semi' in s2 or 'bi' in s2 or 'quin' in s2:
                return 'Semi'
            if 'month' in s2 or s2.startswith('m'):
                return 'Monthly'
            t = s.strip().title()
            return t if t in ('Daily','Weekly','Semi','Monthly') else 'Daily'

        if payment_term is None:
            pt = _norm_term(old_row.get("payment_term") or "Daily")
        else:
            pt = _norm_term(payment_term)

        if payment_amount is None:
            try:
                pa = float(old_row.get("payment_amount") or 0.0)
            except Exception:
                pa = 0.0
        else:
            try:
                pa = float(str(payment_amount).replace(',', '.').strip()) if payment_amount not in (None, '') else 0.0
            except Exception:
                pa = 0.0

        if payment_mode is None:
            pm = _spina__merge_payment_mode(old_row.get("payment_mode"))
        else:
            pm = _spina__merge_payment_mode(payment_mode)

        def _norm_weekday(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return ''
            key = s[:3].strip().lower()
            mp = {
                'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
                'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
            }
            return mp.get(key, '')

        def _norm_dom(v):
            try:
                if v in (None, ''):
                    return None
                n = int(str(v).strip())
                return n if 1 <= n <= 31 else None
            except Exception:
                return None

        if due_weekday is None:
            dwd = _norm_weekday(old_row.get("due_weekday") or "")
        else:
            dwd = _norm_weekday(due_weekday)
        if semi_due_day1 is None:
            sd1 = _norm_dom(old_row.get("semi_due_day1"))
        else:
            sd1 = _norm_dom(semi_due_day1)
        if semi_due_day2 is None:
            sd2 = _norm_dom(old_row.get("semi_due_day2"))
        else:
            sd2 = _norm_dom(semi_due_day2)
        if monthly_due_day is None:
            mdd = _norm_dom(old_row.get("monthly_due_day"))
        else:
            mdd = _norm_dom(monthly_due_day)

        if flex_due_rule is None:
            try:
                fdr = str(old_row.get("flex_due_rule") or "").strip()
            except Exception:
                fdr = ""
        else:
            try:
                fdr = str(flex_due_rule or "").strip()
            except Exception:
                fdr = ""

        # new_until (optional; allow blank to clear)
        if new_until is None:
            nu = old_row.get("new_until") or ""
        else:
            nu = str(new_until).strip()
            if nu:
                try:
                    datetime.strptime(nu[:10], "%Y-%m-%d")
                except Exception:
                    nu = ""

        # pay_start_offset_days
        if pay_start_offset_days is None:
            psod = old_row.get("pay_start_offset_days")
            try:
                psod = int(psod or 0)
            except Exception:
                psod = 0
            psod = 1 if psod >= 1 else 0
        else:
            try:
                psod = int(pay_start_offset_days or 0)
            except Exception:
                psod = 0
            psod = 1 if psod >= 1 else 0

        # Perform update (use uid if available; fallback to name+loan_type)
        try:
            if uid:
                cur.execute(
                    """UPDATE clients
                           SET name=?,
                               contact_number=?,
                               principal=?,
                               interest_rate=?,
                               interest_amount=?,
                               total_to_pay=?,
                               date_released=?,
                               due_date=?,
                               area=?,
                               new_until=?,
                               pay_start_offset_days=?,
                               payment_term=?,
                               payment_amount=?,
                               payment_mode=?,
                               due_weekday=?,
                               semi_due_day1=?,
                               semi_due_day2=?,
                               monthly_due_day=?,
                               flex_due_rule=?
                         WHERE client_uid=?""",
                    (name_new, cn, p, r, intr, total, dr, due, (area_val or ''), nu, psod, pt, pa, pm, dwd, sd1, sd2, mdd, fdr, uid)
                )
            else:
                cur.execute(
                    """UPDATE clients
                           SET name=?,
                               contact_number=?,
                               principal=?,
                               interest_rate=?,
                               interest_amount=?,
                               total_to_pay=?,
                               date_released=?,
                               due_date=?,
                               area=?,
                               new_until=?,
                               pay_start_offset_days=?,
                               payment_term=?,
                               payment_amount=?,
                               payment_mode=?,
                               due_weekday=?,
                               semi_due_day1=?,
                               semi_due_day2=?,
                               monthly_due_day=?,
                               flex_due_rule=?
                         WHERE name=? AND loan_type=?""",
                    (name_new, cn, p, r, intr, total, dr, due, (area_val or ''), nu, psod, pt, pa, pm, dwd, sd1, sd2, mdd, fdr, old_name, lt)
                )

            # If name changed, keep transactions in sync
            try:
                if name_new and name_new != old_name:
                    fixed = 0
                    if uid:
                        try:
                            fixed = int(self._sync_transactions_for_client_uid(uid, loan_type=lt, force_name=name_new) or 0)
                        except Exception:
                            fixed = 0
                    if not fixed:
                        cur.execute("UPDATE transactions SET name=? WHERE name=? AND loan_type=?", (name_new, old_name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0125', 'suppressed exception excpass_0125', __spina_exc)
                pass
            # If name changed, migrate any legacy name-based notes to stable-id keys (prevents orphaned notes)
            try:
                if name_new and name_new != old_name:
                    _migrate_legacy_notes_by_name(
                        old_name=old_name,
                        loan_type=lt,
                        client_uid=uid or (old_row.get("client_uid") if isinstance(old_row, dict) else None),
                        person_uid=(old_row.get("person_uid") if isinstance(old_row, dict) else None),
                    )
            except Exception as e:
                _log_exc("notes:migrate_on_rename", e)


            self.conn.commit()
            try:
                from spina_app.area_hierarchy_ops import sync_client_area_uid_from_path
                _area_sync_uid = uid or (
                    old_row.get("client_uid") if isinstance(old_row, dict) else ""
                )
                if _area_sync_uid:
                    sync_client_area_uid_from_path(self.conn, _area_sync_uid)
            except Exception as __spina_exc:
                _log_suppressed_once(
                    'area_uid_sync_update',
                    'suppressed client Area UID sync after update',
                    __spina_exc,
                )
                pass

            # Log history
            try:
                new_row = self.get_client_by_uid(uid) if uid else self.get_client_info(name_new, loan_type=lt)
                self._log_client_history(uid or (new_row or {}).get("client_uid", ""), 'UPDATE', old_row=old_row, new_row=new_row or {}, source='clients:update')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0126', 'suppressed exception excpass_0126', __spina_exc)
                pass

            return True
        except Exception:
            return False




    def renew_client(self, name, released_cash, renew_date=None, new_principal=None, loan_type=None, interest_rate=None, note='', pay_start_offset_days=None):
        """Renew a client (reloan). Updates the client row to a new cycle and records an event.

        - released_cash: cash actually released to the client for this renew (for display in reports).
        - new_principal: the new loan principal. If None/blank, defaults to released_cash.
        """
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)

        info = self.get_client_info(name, loan_type=lt) or {}
        # Start-of-payment offset for NEW cycle (0=same-day, 1=next-day)
        # Respect the caller's explicit renew choice. If none was provided, preserve the
        # client's current saved offset instead of silently forcing next-day.
        if pay_start_offset_days is None:
            try:
                psod = int((info or {}).get('pay_start_offset_days') or 0)
            except Exception:
                psod = 0
        else:
            try:
                psod = int(pay_start_offset_days or 0)
            except Exception:
                psod = 0
        psod = 1 if psod >= 1 else 0

        if not info:
            return False

        uid = (info.get('client_uid') or '').strip()
        if not uid:
            # best-effort: fall back to name+type (older DB) but renewals history needs uid
            try:
                uid = self.get_client_uid(name, loan_type=lt) or ''
                uid = (uid or '').strip()
            except Exception:
                uid = ''

        # Parse date
        if not renew_date:
            renew_date = date.today().strftime("%Y-%m-%d")
        try:
            datetime.strptime(str(renew_date)[:10], "%Y-%m-%d")
            rd = str(renew_date)[:10]
        except Exception:
            rd = date.today().strftime("%Y-%m-%d")

        # Cash / principal
        try:
            rc = float(released_cash or 0)
        except Exception:
            rc = 0.0
        if new_principal is None or str(new_principal).strip() == '':
            new_principal = rc
        try:
            p = float(new_principal or 0)
        except Exception:
            p = 0.0

        # Interest rate
        try:
            r = float(interest_rate) if interest_rate is not None else float(info.get('interest_rate') or 0.20)
            if r > 1.0:
                r = r / 100.0
        except Exception:
            r = 0.20

        if lt == '7x7':
            r = 0.0

        intr = round(p * r, 2)
        total = round(p + intr, 2)

        due_days = 49 if lt == '7x7' else 120
        try:
            due = (datetime.strptime(rd, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")
        except Exception:
            due = rd

        # Old row for history
        old_row = dict(info)

        def _ensure_renewals_table():
            try:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS renewals (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        client_uid TEXT,
                        loan_type TEXT DEFAULT 'Regular',
                        renew_date TEXT NOT NULL,
                        released_cash REAL DEFAULT 0,
                        principal_after REAL DEFAULT 0,
                        interest_rate REAL DEFAULT 0,
                        note TEXT,
                        created_at TEXT
                    )
                """)
                # Legacy DB safety: make sure an older renewals table has the columns used below.
                try:
                    cols = [r[1] for r in cur.execute("PRAGMA table_info(renewals)").fetchall()]
                except Exception:
                    cols = []
                try:
                    if 'loan_type' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN loan_type TEXT DEFAULT 'Regular'")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127a', 'suppressed exception excpass_0127a', __spina_exc)
                    pass
                try:
                    if 'released_cash' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN released_cash REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127b', 'suppressed exception excpass_0127b', __spina_exc)
                    pass
                try:
                    if 'principal_after' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN principal_after REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127c', 'suppressed exception excpass_0127c', __spina_exc)
                    pass
                try:
                    if 'interest_rate' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN interest_rate REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127d', 'suppressed exception excpass_0127d', __spina_exc)
                    pass
                try:
                    if 'note' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN note TEXT")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127e', 'suppressed exception excpass_0127e', __spina_exc)
                    pass
                try:
                    if 'created_at' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN created_at TEXT")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127f', 'suppressed exception excpass_0127f', __spina_exc)
                    pass
                cur.execute("CREATE INDEX IF NOT EXISTS idx_renewals_uid_date ON renewals(client_uid, loan_type, renew_date)")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0127', 'suppressed exception excpass_0127', __spina_exc)
                pass

        _ensure_renewals_table()

        # Write changes atomically
        def _do():
            # Update client row to new cycle
            cur.execute(
                """UPDATE clients
                      SET principal=?,
                          interest_rate=?,
                          interest_amount=?,
                          total_to_pay=?,
                          date_released=?,
                          due_date=?,
                          new_until=NULL,
                          last_released_cash=?,
                          renew_count=COALESCE(renew_count,0)+1
                    WHERE name=? AND loan_type=?""",
                (p, r, intr, total, rd, due, rc, name, lt)
            )

            # Save the renew start-of-payment offset and the exact start date for the new cycle.
            # This avoids wrong-start carryover after renew and keeps reports aligned with the renew choice.
            try:
                cur.execute("UPDATE clients SET pay_start_offset_days=? WHERE name=? AND loan_type=?", (psod, name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0128', 'suppressed exception excpass_0128', __spina_exc)
                pass
            try:
                pstart = (datetime.strptime(rd, "%Y-%m-%d") + timedelta(days=psod)).strftime("%Y-%m-%d")
                cur.execute("UPDATE clients SET payment_start_date=? WHERE name=? AND loan_type=?", (pstart, name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0128_start', 'suppressed exception excpass_0128_start', __spina_exc)
                pass

            # Record renew event (if uid available)
            if uid:
                cur.execute(
                    """INSERT INTO renewals (client_uid, loan_type, renew_date, released_cash, principal_after, interest_rate, note, created_at)
                        VALUES (?,?,?,?,?,?,?, datetime('now'))""",
                    (uid, lt, rd, rc, p, r, (note or '').strip())
                )

        try:
            run_write(_do)
            try:
                self.conn.commit()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0129_commit', 'suppressed exception excpass_0129_commit', __spina_exc)
                raise
        except Exception as e:
            try:
                self._last_renew_error = str(e)
            except Exception:
                pass
            try:
                _log_exc('renew_client', e)
            except Exception:
                pass
            # fallback without retry wrapper
            try:
                try:
                    self.conn.rollback()
                except Exception:
                    pass
                _do()
                self.conn.commit()
            except Exception as e2:
                try:
                    self._last_renew_error = str(e2)
                except Exception:
                    pass
                try:
                    _log_exc('renew_client:fallback', e2)
                except Exception:
                    pass
                return False

        # Log client history
        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(new_row.get('client_uid') or uid, 'RENEW', old_row=old_row, new_row=new_row, source='clients:renew', note=(note or '').strip())
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0130', 'suppressed exception excpass_0130', __spina_exc)
            pass

        return True

    def get_renewal_stats(self, client_uid, loan_type=None):
        """Return (renew_count, last_released_cash, last_release_date).

        - renew_count counts renew events (not including the original loan release).
        - last_released_cash is the last recorded released cash; if none, returns None.
        """
        lt = self._effective_lt(loan_type)
        uid = (client_uid or '').strip()
        if not uid:
            return (0, None, None)

        cur = self.conn.cursor()

        # Prefer renewals table
        try:
            r = cur.execute(
                "SELECT COUNT(*) AS cnt FROM renewals WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')",
                (uid, lt)
            ).fetchone()
            cnt = int(r[0] if r else 0)

            last = cur.execute(
                "SELECT renew_date, released_cash FROM renewals WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') ORDER BY date(renew_date) DESC, id DESC LIMIT 1",
                (uid, lt)
            ).fetchone()
            if last:
                try:
                    last_date = last[0]
                except Exception:
                    last_date = None
                try:
                    last_cash = float(last[1] or 0)
                except Exception:
                    last_cash = None
            else:
                last_date = None
                last_cash = None
            return (cnt, last_cash, last_date)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0131', 'suppressed exception excpass_0131', __spina_exc)
            pass

        # Fallback to clients columns (if present)
        try:
            row = cur.execute("SELECT renew_count, last_released_cash, date_released FROM clients WHERE client_uid=? LIMIT 1", (uid,)).fetchone()
            if row:
                try:
                    cnt = int(row[0] or 0)
                except Exception:
                    cnt = 0
                try:
                    last_cash = float(row[1]) if row[1] is not None else None
                except Exception:
                    last_cash = None
                try:
                    last_date = row[2]
                except Exception:
                    last_date = None
                return (cnt, last_cash, last_date)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0132', 'suppressed exception excpass_0132', __spina_exc)
            pass

        return (0, None, None)


    def delete_client(self, name, loan_type=None):
        """Delete a client and related transactions for the given loan_type (history is written)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        uid = (old_row.get("client_uid") or "").strip()

        # Count transactions (note only)
        tx_count = 0
        try:
            row = cur.execute("SELECT COUNT(*) AS c FROM transactions WHERE name=? AND loan_type=?", (name, lt)).fetchone()
            tx_count = int(row["c"] if isinstance(row, sqlite3.Row) else row[0])
        except Exception:
            tx_count = 0

        cur.execute("DELETE FROM transactions WHERE name = ? AND loan_type = ?", (name, lt))
        cur.execute("DELETE FROM clients WHERE name = ? AND loan_type = ?", (name, lt))
        self.conn.commit()

        try:
            self._log_client_history(uid, 'DELETE', old_row=old_row, new_row=None, source='clients:delete', note=f"deleted_transactions={tx_count}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0133', 'suppressed exception excpass_0133', __spina_exc)
            pass
    def _ensure_archive_columns(self, cur=None):
        """Best-effort: ensure archive columns exist for older DBs."""
        c = cur or self.conn.cursor()
        try:
            c.execute("ALTER TABLE clients ADD COLUMN is_archived INTEGER DEFAULT 0")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0134', 'suppressed exception excpass_0134', __spina_exc)
            pass
        try:
            c.execute("ALTER TABLE clients ADD COLUMN archived_at TEXT")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0135', 'suppressed exception excpass_0135', __spina_exc)
            pass
        try:
            c.execute("CREATE INDEX IF NOT EXISTS idx_clients_is_archived ON clients(is_archived)")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0136', 'suppressed exception excpass_0136', __spina_exc)
            pass

    def archive_client(self, name, loan_type=None):
        """Soft-delete: hide the client (keeps transactions/history)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        self._ensure_archive_columns(cur)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        if not old_row:
            raise ValueError("Client not found.")
        uid = (old_row.get("client_uid") or "").strip()

        cur.execute(
            "UPDATE clients SET is_archived=1, archived_at=datetime('now') WHERE name=? AND loan_type=?",
            (name, lt),
        )
        self.conn.commit()

        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(uid, "ARCHIVE", old_row=old_row, new_row=new_row, source="clients:archive")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0137', 'suppressed exception excpass_0137', __spina_exc)
            pass
        return True

    def restore_client(self, name, loan_type=None):
        """Restore a previously archived client by (name, loan_type)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        self._ensure_archive_columns(cur)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        if not old_row:
            raise ValueError("Client not found.")
        uid = (old_row.get("client_uid") or "").strip()

        cur.execute(
            "UPDATE clients SET is_archived=0, archived_at=NULL WHERE name=? AND loan_type=?",
            (name, lt),
        )
        self.conn.commit()

        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(uid, "RESTORE", old_row=old_row, new_row=new_row, source="clients:restore")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0138', 'suppressed exception excpass_0138', __spina_exc)
            pass
        return True

    def restore_client_by_uid(self, client_uid):
        """Restore a previously archived client by client_uid."""
        if not client_uid:
            raise ValueError("Missing client UID.")
        cur = self.conn.cursor()
        self._ensure_archive_columns(cur)
        r = None
        try:
            r = cur.execute("SELECT name, loan_type FROM clients WHERE client_uid=?", (client_uid,)).fetchone()
        except Exception:
            r = None
        if not r:
            raise ValueError("Client not found.")
        try:
            name = r["name"] if isinstance(r, sqlite3.Row) else r[0]
            lt = r["loan_type"] if isinstance(r, sqlite3.Row) else r[1]
        except Exception:
            name, lt = r[0], r[1]
        return self.restore_client(name, loan_type=lt)

    def get_archived_clients(self, search=None, loan_type=None):
        """List archived clients for restore UI."""
        cur = self.conn.cursor()
        lt = (loan_type or "").strip()
        if lt:
            lt = self._norm_lt(lt)

        self._ensure_archive_columns(cur)

        term = (search or "").strip()
        like = f"%{term}%"
        q = "SELECT name, loan_type, area, client_uid, archived_at FROM clients WHERE COALESCE(is_archived,0)=1"
        params = []
        if lt:
            q += " AND loan_type=?"
            params.append(lt)
        if term:
            q += " AND name LIKE ?"
            params.append(like)
        q += " ORDER BY archived_at DESC, name COLLATE NOCASE"
        try:
            rows = cur.execute(q, params).fetchall()
            out = []
            for r in rows:
                if isinstance(r, sqlite3.Row):
                    out.append(dict(r))
                else:
                    out.append({"name": r[0], "loan_type": r[1], "area": r[2], "client_uid": r[3], "archived_at": r[4]})
            return out
        except Exception:
            return []







    def get_unpaired_7x7_names(self, search=None, search_by='all'):
        """Return 7x7 client names that have NO Regular record and are NOT linked.

        Used so 7x7-only clients can still be managed from the Regular view (appear at the bottom)
        and included in Collector Route prints.

        Rules:
          - loan_type must be '7x7'
          - there is no same-name Regular record
          - person_uid is blank/empty (not linked)
        """
        try:
            # Candidates by search filter (name/area/etc)
            candidates = self.get_all_clients(search=search, loan_type='7x7', search_by=search_by) or []
        except Exception:
            candidates = []
        out = []
        for nm in candidates:
            try:
                name = (nm or '').strip()
            except Exception:
                name = nm
            if not name:
                continue
            # Skip if a Regular record exists (suggested-link case, not 7x7-only)
            try:
                if self.get_client_info(name, loan_type='Regular'):
                    continue
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0140', 'suppressed exception excpass_0140', __spina_exc)
                pass
            # Skip if already linked (has person_uid)
            try:
                info7 = self.get_client_info(name, loan_type='7x7') or {}
                pu = (info7.get('person_uid') or '').strip()
                if pu:
                    continue
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0141', 'suppressed exception excpass_0141', __spina_exc)
                pass
            out.append(name)
        # Stable case-insensitive sort
        try:
            out = sorted(out, key=lambda s: str(s).lower())
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0142', 'suppressed exception excpass_0142', __spina_exc)
            pass
        return out


    def fetch_all_clients(self, loan_type=None, include_archived=False):
        """Return list of dict rows for clients (optionally filtered by loan_type)."""
        cur = self.conn.cursor()
        # soft-delete support
        has_archived = False
        try:
            cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
            has_archived = ('is_archived' in cols)
        except Exception:
            has_archived = False
        lt = (loan_type or '').strip()
        if lt:
            if lt.lower().replace(' ', '') in ('7x7','7×7'):
                lt = '7x7'
            else:
                lt = 'Regular'
        try:
            if lt:
                cur.execute(
                    "SELECT name, area, principal, interest_amount, total_to_pay, date_released, due_date, loan_type FROM clients WHERE loan_type = ? " + ("AND COALESCE(is_archived,0)=0 " if ((not include_archived) and has_archived) else "") + "ORDER BY area, name;",
                    (lt,),
                )
            else:
                cur.execute(
                    "SELECT name, area, principal, interest_amount, total_to_pay, date_released, due_date, loan_type FROM clients " + ("WHERE COALESCE(is_archived,0)=0 " if ((not include_archived) and has_archived) else "") + "ORDER BY area, name;"
                )
        except Exception:
            # Older DB fallback (no loan_type)
            if lt:
                cur.execute("SELECT name, '' AS area FROM clients ORDER BY name;")
            else:
                cur.execute("SELECT name, '' AS area FROM clients ORDER BY name;")
        rows = cur.fetchall()
        return [dict(r) for r in rows]



    # -------- Client linking (Regular + 7x7) --------



    def set_link_opt_out_by_uid(self, client_uid, opt_out=1, source='clients:link_opt_out'):
        """Persist opt-out flag so auto-link prompts can be declined."""
        if not client_uid:
            return False
        cur = self.conn.cursor()
        try:
            old_row = self.get_client_by_uid(client_uid) or {}
            cur.execute("UPDATE clients SET link_opt_out=? WHERE client_uid=?", (1 if int(opt_out or 0) else 0, client_uid))
            self.conn.commit()
            try:
                new_row = self.get_client_by_uid(client_uid) or {}
                self._log_client_history(client_uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0143', 'suppressed exception excpass_0143', __spina_exc)
                pass
            return True
        except Exception:
            return False
    def link_client_uids(self, uid_a, uid_b, source='clients:link'):
        """Link two client rows (typically Regular + 7x7) by assigning the same person_uid.

        Safety rules:
        - Prevent linking the same row to itself.
        - Prevent linking two rows of the same loan_type (to avoid accidental merges).
        - Prevent merging two different existing person_uid groups (unlink first).
        """
        self._set_last_error('')
        uid_a = (uid_a or '').strip()
        uid_b = (uid_b or '').strip()
        if not uid_a or not uid_b:
            self._set_last_error('Missing client UID(s).')
            return False
        if uid_a == uid_b:
            self._set_last_error('Cannot link a client to itself.')
            return False

        cur = self.conn.cursor()
        try:
            a_old = self.get_client_by_uid(uid_a) or {}
            b_old = self.get_client_by_uid(uid_b) or {}
            if not a_old or not b_old:
                self._set_last_error('Client record not found (UID missing in database).')
                return False

            lt_a = (a_old.get('loan_type') or 'Regular').strip()
            lt_b = (b_old.get('loan_type') or 'Regular').strip()
            if lt_a == lt_b:
                self._set_last_error(f"Cannot link two '{lt_a}' records. Linking is intended for Regular + 7x7 only.")
                return False

            pu_a = (a_old.get('person_uid') or '').strip()
            pu_b = (b_old.get('person_uid') or '').strip()

            # Strict rule: do not allow linking if either record is already part of any link group.
            # This keeps links as 1 Regular <-> 1 7x7 only. User must unlink first.
            if pu_a and pu_b and pu_a == pu_b:
                self._set_last_error('These records are already linked.')
                return False

            if pu_a and pu_b and pu_a != pu_b:
                self._set_last_error('These records are already linked to different people. Unlink first, then link again.')
                return False

            if pu_a or pu_b:
                if pu_a:
                    self._set_last_error(f"'{a_old.get('name') or 'Selected client'}' is already linked. Unlink it first.")
                else:
                    self._set_last_error(f"'{b_old.get('name') or 'Target client'}' is already linked. Unlink it first.")
                return False

            # Choose or create person_uid
            pu = ''
            try:
                import uuid
                pu = uuid.uuid4().hex
            except Exception:
                pu = str(datetime.now().timestamp()).replace('.', '')

            # Apply to both (and clear opt-out)
            cur.execute("UPDATE clients SET person_uid=?, link_opt_out=0 WHERE client_uid=?", (pu, uid_a))
            cur.execute("UPDATE clients SET person_uid=?, link_opt_out=0 WHERE client_uid=?", (pu, uid_b))
            self.conn.commit()

            # History log (before/after)
            try:
                a_new = self.get_client_by_uid(uid_a) or {}
                self._log_client_history(uid_a, 'UPDATE', old_row=a_old, new_row=a_new, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0144', 'suppressed exception excpass_0144', __spina_exc)
                pass
            try:
                b_new = self.get_client_by_uid(uid_b) or {}
                self._log_client_history(uid_b, 'UPDATE', old_row=b_old, new_row=b_new, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0145', 'suppressed exception excpass_0145', __spina_exc)
                pass
            return True
        except Exception as e:
            self._set_last_error(f'Link failed: {e}')
            try:
                self.conn.rollback()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0146', 'suppressed exception excpass_0146', __spina_exc)
                pass
            return False





    def unlink_person_uid(self, person_uid, source='clients:unlink'):
        """Unlink all rows that share this person_uid (clears person_uid)."""
        pu = (person_uid or '').strip()
        if not pu:
            return False
        cur = self.conn.cursor()
        try:
            rows = cur.execute("SELECT client_uid FROM clients WHERE person_uid=?", (pu,)).fetchall() or []
            for (uid,) in rows:
                try:
                    old_row = self.get_client_by_uid(uid) or {}
                    cur.execute("UPDATE clients SET person_uid='', link_opt_out=0 WHERE client_uid=?", (uid,))
                    # log each
                    try:
                        new_row = self.get_client_by_uid(uid) or {}
                        self._log_client_history(uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0147', 'suppressed exception excpass_0147', __spina_exc)
                        pass
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0148', 'suppressed exception excpass_0148', __spina_exc)
                    pass
            self.conn.commit()
            return True
        except Exception:
            return False



    # Client history / audit



    def _sync_transactions_for_client_uid(self, client_uid, loan_type=None, force_name=None):
        """Best-effort repair for transaction rows tied to one client.
        Keeps `transactions.client_uid` and `transactions.name` aligned to the current client row.
        Returns the number of transaction rows updated.
        """
        uid = (client_uid or '').strip()
        if not uid:
            return 0
        cur = self.conn.cursor()
        try:
            row = cur.execute(
                "SELECT name, loan_type FROM clients WHERE client_uid=? LIMIT 1",
                (uid,)
            ).fetchone()
            if not row:
                return 0
            current_name = ((force_name if force_name is not None else (row["name"] if isinstance(row, sqlite3.Row) else row[0])) or '').strip()
            current_lt = self._effective_lt((row["loan_type"] if isinstance(row, sqlite3.Row) else row[1]) if row else loan_type)
            try:
                cur.execute(
                    """
                    UPDATE transactions
                       SET client_uid=?,
                           name=?
                     WHERE client_uid=?
                       AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')
                       AND IFNULL(TRIM(name),'') <> IFNULL(TRIM(?),'')
                       AND NOT EXISTS (
                           SELECT 1
                             FROM databank_day_close dc
                            WHERE dc.close_date = date(transactions.date)
                              AND dc.loan_type = '__ALL__'
                              AND COALESCE(dc.is_closed, 0) = 1
                       )
                    """,
                    (uid, current_name, uid, current_lt, current_name)
                )
                fixed = int(cur.rowcount or 0)
            except Exception:
                fixed = 0
            try:
                cur.execute(
                    """
                    UPDATE transactions
                       SET client_uid=?,
                           name=?
                     WHERE (client_uid IS NULL OR TRIM(client_uid)='')
                       AND TRIM(IFNULL(name,''))=?
                       AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')
                       AND NOT EXISTS (
                           SELECT 1
                             FROM databank_day_close dc
                            WHERE dc.close_date = date(transactions.date)
                              AND dc.loan_type = '__ALL__'
                              AND COALESCE(dc.is_closed, 0) = 1
                       )
                    """,
                    (uid, current_name, current_name, current_lt)
                )
                fixed += int(cur.rowcount or 0)
            except Exception:
                pass
            return fixed
        except Exception:
            return 0

    def repair_transaction_identity_links(self):
        """Best-effort global repair for transaction/client identity drift.
        - backfills missing transaction.client_uid from exact current (name, loan_type)
        - normalizes transaction.name from the current clients.name when client_uid is present
        Returns a small stats dict.
        """
        cur = self.conn.cursor()
        stats = {"backfilled_uid": 0, "synced_name": 0}
        try:
            cur.execute("CREATE INDEX IF NOT EXISTS idx_tx_client_uid_type_date ON transactions(client_uid, loan_type, date)")
        except Exception:
            pass
        try:
            cur.execute(
                """
                UPDATE transactions
                   SET client_uid = (
                       SELECT c.client_uid
                         FROM clients c
                        WHERE TRIM(IFNULL(c.name,'')) = TRIM(IFNULL(transactions.name,''))
                          AND IFNULL(NULLIF(TRIM(c.loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(transactions.loan_type),''),'Regular')
                        LIMIT 1
                   )
                 WHERE client_uid IS NULL OR TRIM(client_uid)=''
                """
            )
            stats["backfilled_uid"] = int(cur.rowcount or 0)
        except Exception:
            pass
        try:
            cur.execute(
                """
                UPDATE transactions
                   SET name = (
                       SELECT c.name
                         FROM clients c
                        WHERE c.client_uid = transactions.client_uid
                        LIMIT 1
                   )
                 WHERE client_uid IS NOT NULL
                   AND TRIM(client_uid)<>''
                   AND EXISTS (
                       SELECT 1
                         FROM clients c
                        WHERE c.client_uid = transactions.client_uid
                          AND TRIM(IFNULL(c.name,'')) <> TRIM(IFNULL(transactions.name,''))
                   )
                """
            )
            stats["synced_name"] = int(cur.rowcount or 0)
        except Exception:
            pass
        return stats



    def _log_client_history(self, client_uid, action, old_row=None, new_row=None, source='', note=''):
        """Append-only audit entry. old_row/new_row are dicts or None."""
        uid = (client_uid or '').strip()
        if not uid:
            # Best-effort: try to derive uid from new/old row
            try:
                uid = (new_row or old_row or {}).get("client_uid", "") or ""
            except Exception:
                uid = ""
        uid = (uid or "").strip()
        if not uid:
            return False

        def _safe_json(obj):
            try:
                return json.dumps(obj, ensure_ascii=False, default=str, sort_keys=True)
            except Exception:
                try:
                    return json.dumps(str(obj), ensure_ascii=False)
                except Exception:
                    return ""

        nb = (old_row or {}).get("name") if isinstance(old_row, dict) else None
        na = (new_row or {}).get("name") if isinstance(new_row, dict) else None
        ltb = (old_row or {}).get("loan_type") if isinstance(old_row, dict) else None
        lta = (new_row or {}).get("loan_type") if isinstance(new_row, dict) else None

        cur = self.conn.cursor()
        try:
            cur.execute(
                """INSERT INTO client_history
                   (client_uid, name_before, name_after, loan_type_before, loan_type_after, action, changed_at, old_json, new_json, source, note)
                   VALUES (?,?,?,?,?, ?, datetime('now'), ?,?,?,?)""",
                (uid, nb, na, ltb, lta, action, _safe_json(old_row), _safe_json(new_row), (source or ''), (note or ''))
            )
            self.conn.commit()
            return True
        except Exception:
            return False



    # Transaction history / Data Bank audit





    def _log_transaction_history(self, client_uid, action, old_row=None, new_row=None, source='', note=''):
        """Append-only audit entry for Data Bank transactions."""
        uid = (client_uid or '').strip()
        # Derive UID from rows if needed
        if not uid:
            try:
                uid = ((new_row or old_row or {}).get("client_uid") or "").strip()
            except Exception:
                uid = ""
        # Derive uid by (name, loan_type) if still missing
        if not uid:
            try:
                nm = (new_row or old_row or {}).get("name")
                lt = (new_row or old_row or {}).get("loan_type")
                uid = (self.get_client_uid(nm, loan_type=lt) or "").strip()
            except Exception:
                uid = ""
        # Still allow logging even if uid is missing (best-effort)
        person_uid = ""
        try:
            if uid:
                person_uid = (self.get_person_uid_for_client_uid(uid) or "").strip()
        except Exception:
            person_uid = ""

        def _safe_json(obj):
            try:
                return json.dumps(obj, ensure_ascii=False, default=str, sort_keys=True)
            except Exception:
                try:
                    return json.dumps(str(obj), ensure_ascii=False)
                except Exception:
                    return ""

        # identity fields
        nm = ""
        lt = ""
        dt = ""
        try:
            src_row = (new_row or old_row or {}) or {}
            nm = (src_row.get("name") or "") if isinstance(src_row, dict) else ""
            lt = (src_row.get("loan_type") or "") if isinstance(src_row, dict) else ""
            dt = (src_row.get("date") or "") if isinstance(src_row, dict) else ""
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0151', 'suppressed exception excpass_0151', __spina_exc)
            pass

        cur = self.conn.cursor()
        try:
            cur.execute(
                """INSERT INTO transaction_history
                   (person_uid, client_uid, name, loan_type, date, action, changed_at, old_json, new_json, source, note)
                   VALUES (?,?,?,?,?, ?, datetime('now'), ?,?,?,?)""",
                (
                    (person_uid or ""),
                    (uid or ""),
                    (nm or ""),
                    (lt or ""),
                    (dt or ""),
                    (action or ""),
                    _safe_json(old_row),
                    _safe_json(new_row),
                    (source or ""),
                    (note or ""),
                )
            )
            self.conn.commit()
            return True
        except Exception:
            return False



    def _audit_parse_json_payload(self, raw_json):
        import json
        if isinstance(raw_json, dict):
            try:
                return dict(raw_json)
            except Exception:
                return raw_json
        raw = raw_json
        if raw is None:
            return {}
        try:
            raw = str(raw).strip()
        except Exception:
            return {}
        if not raw:
            return {}
        try:
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}



    def get_audit_renewal_rows(self, start_date=None, end_date=None, loan_type=None, limit=1000):
        """Return append-only RENEW audit rows."""
        cur = self.conn.cursor()
        lim = max(1, min(int(limit or 1000), 5000))
        lt = self._effective_lt(loan_type) if loan_type else ''
        sql = ["SELECT * FROM client_history WHERE action='RENEW'"]
        params = []
        if start_date:
            sql.append("AND date(changed_at) >= date(?)")
            params.append(str(start_date)[:10])
        if end_date:
            sql.append("AND date(changed_at) <= date(?)")
            params.append(str(end_date)[:10])
        if lt:
            sql.append("AND IFNULL(NULLIF(TRIM(COALESCE(loan_type_after, loan_type_before)),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')")
            params.append(lt)
        sql.append("ORDER BY datetime(changed_at) DESC, id DESC LIMIT ?")
        params.append(lim)
        try:
            rows = cur.execute(" ".join(sql), tuple(params)).fetchall()
        except Exception:
            return []

        out = []
        for r in (rows or []):
            try:
                d = dict(r)
            except Exception:
                d = {}
            old_payload = self._audit_parse_json_payload(d.get('old_json'))
            new_payload = self._audit_parse_json_payload(d.get('new_json'))
            try:
                renew_date = (new_payload.get('date_released') or '').strip()
            except Exception:
                renew_date = ''
            out.append({
                'ts': d.get('changed_at') or '',
                'client_uid': (d.get('client_uid') or new_payload.get('client_uid') or old_payload.get('client_uid') or '').strip(),
                'person_uid': (new_payload.get('person_uid') or old_payload.get('person_uid') or '').strip(),
                'name': (new_payload.get('name') or old_payload.get('name') or d.get('name_after') or d.get('name_before') or '').strip(),
                'loan_type': (new_payload.get('loan_type') or old_payload.get('loan_type') or d.get('loan_type_after') or d.get('loan_type_before') or 'Regular').strip() or 'Regular',
                'renew_date': renew_date,
                'old_start_date': (old_payload.get('payment_start_date') or '').strip(),
                'new_start_date': (new_payload.get('payment_start_date') or '').strip(),
                'old_principal': old_payload.get('principal', 0),
                'new_principal': new_payload.get('principal', 0),
                'released_cash': new_payload.get('last_released_cash', 0),
                'renew_count': new_payload.get('renew_count', 0),
                'area': (new_payload.get('area') or old_payload.get('area') or '').strip(),
                'payment_term': (new_payload.get('payment_term') or '').strip(),
                'payment_amount': new_payload.get('payment_amount', 0),
                'source': (d.get('source') or '').strip(),
                'note': (d.get('note') or '').strip(),
                'old_json': d.get('old_json') or '',
                'new_json': d.get('new_json') or '',
            })
        return out

    def _databank_day_close_bucket(self, loan_type=None):
        # Combined daily close bucket for all Data Bank loan types (Regular + 7x7).
        return '__ALL__'

    def _dayclose_norm_workflow(self, workflow_status, variance=0.0, is_closed=True):
        wf = str(workflow_status or '').strip().title()
        if wf in ('Open', 'Pending', 'Resolved'):
            return wf
        if not bool(is_closed):
            return 'Open'
        try:
            vv = float(variance or 0.0)
        except Exception:
            vv = 0.0
        return 'Resolved' if abs(vv) < 0.005 else 'Pending'

    def _dayclose_variance_status(self, variance):
        try:
            vv = float(variance or 0.0)
        except Exception:
            vv = 0.0
        if abs(vv) < 0.005:
            return 'Balanced'
        return 'Overage' if vv > 0 else 'Short'

    def get_databank_daily_total(self, date_s, loan_type=None):
        cur = self.conn.cursor()
        raw_lt = (str(loan_type or '').strip())
        try:
            if (not raw_lt) or (raw_lt.upper() in ('ALL', 'COMBINED', '__ALL__')):
                row = cur.execute(
                    """
                    SELECT COALESCE(SUM(COALESCE(payment, 0)), 0)
                    FROM transactions
                    WHERE date(date) = date(?)
                    """,
                    (date_s,),
                ).fetchone()
            else:
                lt = self._effective_lt(raw_lt)
                row = cur.execute(
                    """
                    SELECT COALESCE(SUM(COALESCE(payment, 0)), 0)
                    FROM transactions
                    WHERE date(date) = date(?)
                      AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')
                    """,
                    (date_s, lt),
                ).fetchone()
            if not row:
                return 0.0
            try:
                return float(row[0] or 0.0)
            except Exception:
                return 0.0
        except Exception:
            return 0.0

    def get_databank_day_close(self, date_s, loan_type=None):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        try:
            row = cur.execute(
                "SELECT * FROM databank_day_close WHERE close_date=? AND loan_type=? LIMIT 1",
                (date_s, bucket),
            ).fetchone()
            if not row:
                return None
            d = dict(row)
            try:
                d['expected_amount'] = round(float(d.get('expected_amount') or 0.0), 2)
            except Exception:
                d['expected_amount'] = 0.0
            try:
                d['actual_cash'] = round(float(d.get('actual_cash') or 0.0), 2)
            except Exception:
                d['actual_cash'] = 0.0
            try:
                d['variance'] = round(float(d.get('variance') or 0.0), 2)
            except Exception:
                d['variance'] = round(float(d.get('actual_cash') or 0.0) - float(d.get('expected_amount') or 0.0), 2)
            d['variance_status'] = (d.get('variance_status') or self._dayclose_variance_status(d.get('variance'))).strip() or 'Balanced'
            d['variance_workflow_status'] = self._dayclose_norm_workflow(
                d.get('variance_workflow_status'),
                variance=d.get('variance'),
                is_closed=bool(int(d.get('is_closed') or 0)),
            )
            return d
        except Exception:
            return None

    def is_databank_day_closed(self, date_s, loan_type=None):
        rec = self.get_databank_day_close(date_s, loan_type=loan_type) or {}
        try:
            return bool(int(rec.get('is_closed') or 0))
        except Exception:
            return False

    def _append_databank_day_close_history(self, date_s, action, rec=None, actor='', note='', loan_type=None, source='databank:history', payload=None):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        rr = dict(rec or {})
        try:
            payload_json = json.dumps(payload or {}, ensure_ascii=False, default=str, sort_keys=True)
        except Exception:
            payload_json = ''
        try:
            cur.execute(
                """
                INSERT INTO databank_day_close_history
                    (close_date, loan_type, action, variance_status, workflow_status,
                     expected_amount, actual_cash, variance, note, actor, event_at, source, payload_json)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), ?, ?)
                """,
                (
                    date_s,
                    bucket,
                    str(action or '').strip() or 'update',
                    (rr.get('variance_status') or '').strip(),
                    self._dayclose_norm_workflow(rr.get('variance_workflow_status'), variance=rr.get('variance'), is_closed=bool(int(rr.get('is_closed') or 0)) if rr else True),
                    round(float(rr.get('expected_amount') or 0.0), 2),
                    round(float(rr.get('actual_cash') or 0.0), 2),
                    round(float(rr.get('variance') or 0.0), 2),
                    str(note if note is not None else rr.get('note') or ''),
                    str(actor or '').strip(),
                    source or 'databank:history',
                    payload_json,
                ),
            )
        except Exception as e:
            try:
                _log_exc('databank_day_close_history:insert', e)
            except Exception:
                pass

    def list_databank_day_close_history(self, date_s, loan_type=None, limit=200):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        try:
            rows = cur.execute(
                """
                SELECT *
                  FROM databank_day_close_history
                 WHERE close_date=? AND loan_type=?
                 ORDER BY datetime(event_at) DESC, id DESC
                 LIMIT ?
                """,
                (date_s, bucket, int(limit or 200)),
            ).fetchall()
        except Exception:
            return []
        out = []
        for r in (rows or []):
            try:
                d = dict(r)
            except Exception:
                d = {}
            d['workflow_status'] = self._dayclose_norm_workflow(d.get('workflow_status'), variance=d.get('variance'), is_closed=True)
            out.append(d)
        return out

    def list_databank_day_collectors(self, date_s, loan_type=None):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        try:
            rows = cur.execute(
                """
                SELECT *
                  FROM databank_day_collector_close
                 WHERE close_date=? AND loan_type=?
                 ORDER BY sort_order ASC, collector_name COLLATE NOCASE ASC, id ASC
                """,
                (date_s, bucket),
            ).fetchall()
        except Exception:
            return []
        out = []
        for r in (rows or []):
            try:
                d = dict(r)
            except Exception:
                d = {}
            try:
                d['expected_amount'] = round(float(d.get('expected_amount') or 0.0), 2)
            except Exception:
                d['expected_amount'] = 0.0
            try:
                d['actual_cash'] = round(float(d.get('actual_cash') or 0.0), 2)
            except Exception:
                d['actual_cash'] = 0.0
            try:
                d['variance'] = round(float(d.get('variance') or 0.0), 2)
            except Exception:
                d['variance'] = round(float(d.get('actual_cash') or 0.0) - float(d.get('expected_amount') or 0.0), 2)
            out.append(d)
        return out

    def get_databank_day_collector_totals(self, date_s, loan_type=None):
        rows = self.list_databank_day_collectors(date_s, loan_type=loan_type)
        exp = 0.0
        act = 0.0
        for r in (rows or []):
            try:
                exp += float(r.get('expected_amount') or 0.0)
            except Exception:
                pass
            try:
                act += float(r.get('actual_cash') or 0.0)
            except Exception:
                pass
        exp = round(exp, 2)
        act = round(act, 2)
        var = round(act - exp, 2)
        if abs(var) < 0.005:
            var = 0.0
        return {
            'rows': rows,
            'expected_amount': exp,
            'actual_cash': act,
            'variance': var,
            'variance_status': self._dayclose_variance_status(var),
        }

    def replace_databank_day_collectors(self, date_s, rows, changed_by='', loan_type=None, source='databank:collector_split'):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        cleaned = []
        seen = set()
        for idx, row in enumerate(rows or []):
            try:
                name = str((row or {}).get('collector_name') or '').strip()
            except Exception:
                name = ''
            if not name:
                continue
            key = name.lower()
            if key in seen:
                suffix = 2
                while f"{key}__{suffix}" in seen:
                    suffix += 1
                seen.add(f"{key}__{suffix}")
                name = f"{name} ({suffix})"
            else:
                seen.add(key)
            try:
                expected = round(float((row or {}).get('expected_amount') or 0.0), 2)
            except Exception:
                expected = 0.0
            try:
                actual = round(float((row or {}).get('actual_cash') or 0.0), 2)
            except Exception:
                actual = 0.0
            variance = round(actual - expected, 2)
            if abs(variance) < 0.005:
                variance = 0.0
            cleaned.append({
                'collector_name': name,
                'expected_amount': expected,
                'actual_cash': actual,
                'variance': variance,
                'note': str((row or {}).get('note') or '').strip(),
                'sort_order': idx,
            })
        try:
            cur.execute("DELETE FROM databank_day_collector_close WHERE close_date=? AND loan_type=?", (date_s, bucket))
            for row in cleaned:
                cur.execute(
                    """
                    INSERT INTO databank_day_collector_close
                        (close_date, loan_type, collector_name, expected_amount, actual_cash, variance,
                         note, sort_order, updated_by, created_at, updated_at, source)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'), ?)
                    """,
                    (
                        date_s,
                        bucket,
                        row['collector_name'],
                        row['expected_amount'],
                        row['actual_cash'],
                        row['variance'],
                        row['note'],
                        int(row.get('sort_order') or 0),
                        str(changed_by or '').strip(),
                        source or 'databank:collector_split',
                    ),
                )
            self.conn.commit()
        except Exception:
            self.conn.rollback()
            raise

        rec = self.get_databank_day_close(date_s, loan_type=loan_type) or {
            'close_date': date_s,
            'loan_type': bucket,
            'expected_amount': round(float(self.get_databank_daily_total(date_s, loan_type='__ALL__') or 0.0), 2),
            'actual_cash': 0.0,
            'variance': 0.0,
            'variance_status': 'Balanced',
            'variance_workflow_status': 'Open',
            'is_closed': 0,
            'note': '',
        }
        totals = self.get_databank_day_collector_totals(date_s, loan_type=loan_type)
        self._append_databank_day_close_history(
            date_s,
            'collector_split_saved',
            rec=rec,
            actor=changed_by,
            note=rec.get('note') or '',
            loan_type=loan_type,
            source=source,
            payload={'collector_rows': cleaned, 'collector_totals': totals},
        )
        self.conn.commit()
        return totals

    def set_databank_day_close(self, date_s, actual_cash, note='', closed_by='', loan_type=None, source='databank:close', workflow_status=None, collector_rows=None):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        before = self.get_databank_day_close(date_s, loan_type=loan_type)
        expected = round(float(self.get_databank_daily_total(date_s, loan_type='__ALL__') or 0.0), 2)
        actual = round(float(actual_cash or 0.0), 2)
        variance = round(actual - expected, 2)
        if abs(variance) < 0.005:
            variance = 0.0
        variance_status = self._dayclose_variance_status(variance)
        workflow = self._dayclose_norm_workflow(workflow_status, variance=variance, is_closed=True)
        try:
            cur.execute(
                """
                INSERT INTO databank_day_close
                    (close_date, loan_type, expected_amount, actual_cash, variance, variance_status,
                     variance_workflow_status, is_closed, note, closed_by, closed_at, opened_by, opened_at, updated_at, source)
                VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, datetime('now'), '', NULL, datetime('now'), ?)
                ON CONFLICT(close_date, loan_type) DO UPDATE SET
                    expected_amount=excluded.expected_amount,
                    actual_cash=excluded.actual_cash,
                    variance=excluded.variance,
                    variance_status=excluded.variance_status,
                    variance_workflow_status=excluded.variance_workflow_status,
                    is_closed=1,
                    note=excluded.note,
                    closed_by=excluded.closed_by,
                    closed_at=datetime('now'),
                    updated_at=datetime('now'),
                    source=excluded.source
                """,
                (
                    date_s,
                    bucket,
                    expected,
                    actual,
                    variance,
                    variance_status,
                    workflow,
                    note or '',
                    closed_by or '',
                    source or 'databank:close',
                ),
            )
            if collector_rows is not None:
                self.replace_databank_day_collectors(date_s, collector_rows, changed_by=closed_by, loan_type=loan_type, source=(source or 'databank:close') + ':collectors')
            self.conn.commit()
        except Exception:
            self.conn.rollback()
            raise
        after = self.get_databank_day_close(date_s, loan_type=loan_type)
        self._append_databank_day_close_history(
            date_s,
            'close',
            rec=after,
            actor=closed_by,
            note=note or '',
            loan_type=loan_type,
            source=source,
            payload={
                'before': before or {},
                'after': after or {},
                'collector_totals': self.get_databank_day_collector_totals(date_s, loan_type=loan_type),
            },
        )
        self.conn.commit()
        return after

    def reopen_databank_day(self, date_s, opened_by='', loan_type=None, source='databank:reopen'):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        existing = self.get_databank_day_close(date_s, loan_type=loan_type)
        if not existing:
            expected = round(float(self.get_databank_daily_total(date_s, loan_type='__ALL__') or 0.0), 2)
            cur.execute(
                """
                INSERT INTO databank_day_close
                    (close_date, loan_type, expected_amount, actual_cash, variance, variance_status,
                     variance_workflow_status, is_closed, note, closed_by, closed_at, opened_by, opened_at, updated_at, source)
                VALUES (?, ?, ?, 0, 0, 'Balanced', 'Open', 0, '', '', NULL, ?, datetime('now'), datetime('now'), ?)
                """,
                (date_s, bucket, expected, opened_by or '', source or 'databank:reopen'),
            )
        else:
            cur.execute(
                """
                UPDATE databank_day_close
                   SET is_closed=0,
                       variance_workflow_status='Open',
                       opened_by=?,
                       opened_at=datetime('now'),
                       updated_at=datetime('now'),
                       source=?
                 WHERE close_date=? AND loan_type=?
                """,
                (opened_by or '', source or 'databank:reopen', date_s, bucket),
            )
        self.conn.commit()
        after = self.get_databank_day_close(date_s, loan_type=loan_type)
        self._append_databank_day_close_history(
            date_s,
            'reopen',
            rec=after,
            actor=opened_by,
            note=(after or {}).get('note') or '',
            loan_type=loan_type,
            source=source,
            payload={'after': after or {}},
        )
        self.conn.commit()
        return after

    def set_databank_day_workflow(self, date_s, workflow_status, note='', changed_by='', loan_type=None, source='databank:workflow'):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        existing = self.get_databank_day_close(date_s, loan_type=loan_type)
        if not existing:
            expected = round(float(self.get_databank_daily_total(date_s, loan_type='__ALL__') or 0.0), 2)
            actual = 0.0
            variance = round(actual - expected, 2)
            if abs(variance) < 0.005:
                variance = 0.0
            variance_status = self._dayclose_variance_status(variance)
            workflow = self._dayclose_norm_workflow(workflow_status, variance=variance, is_closed=False)
            cur.execute(
                """
                INSERT INTO databank_day_close
                    (close_date, loan_type, expected_amount, actual_cash, variance, variance_status,
                     variance_workflow_status, is_closed, note, closed_by, closed_at, opened_by, opened_at, updated_at, source)
                VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, '', NULL, ?, datetime('now'), datetime('now'), ?)
                """,
                (date_s, bucket, expected, actual, variance, variance_status, workflow, note or '', changed_by or '', source or 'databank:workflow'),
            )
        else:
            workflow = self._dayclose_norm_workflow(workflow_status, variance=existing.get('variance'), is_closed=bool(int(existing.get('is_closed') or 0)))
            cur.execute(
                """
                UPDATE databank_day_close
                   SET variance_workflow_status=?,
                       note=?,
                       updated_at=datetime('now'),
                       source=?
                 WHERE close_date=? AND loan_type=?
                """,
                (workflow, note or '', source or 'databank:workflow', date_s, bucket),
            )
        self.conn.commit()
        after = self.get_databank_day_close(date_s, loan_type=loan_type)
        self._append_databank_day_close_history(
            date_s,
            'workflow_update',
            rec=after,
            actor=changed_by,
            note=note or '',
            loan_type=loan_type,
            source=source,
            payload={'after': after or {}},
        )
        self.conn.commit()
        return after

    def list_databank_day_close_records(self, start_date=None, end_date=None, loan_type=None):
        cur = self.conn.cursor()
        bucket = self._databank_day_close_bucket(loan_type)
        start_date = (str(start_date or '').strip())
        end_date = (str(end_date or '').strip())
        params = [bucket]
        sql = [
            "SELECT * FROM databank_day_close WHERE loan_type=?"
        ]
        if start_date:
            sql.append("AND date(close_date) >= date(?)")
            params.append(start_date)
        if end_date:
            sql.append("AND date(close_date) <= date(?)")
            params.append(end_date)
        sql.append("ORDER BY date(close_date) DESC, id DESC")
        try:
            rows = cur.execute(" ".join(sql), tuple(params)).fetchall()
        except Exception:
            return []
        out = []
        for r in (rows or []):
            try:
                d = dict(r)
            except Exception:
                d = {}
            ds = (d.get('close_date') or '').strip()
            try:
                d['regular_total'] = round(float(self.get_databank_daily_total(ds, loan_type='Regular') or 0.0), 2)
            except Exception:
                d['regular_total'] = 0.0
            try:
                d['x7_total'] = round(float(self.get_databank_daily_total(ds, loan_type='7x7') or 0.0), 2)
            except Exception:
                d['x7_total'] = 0.0
            try:
                d['expected_amount'] = round(float(d.get('expected_amount') or 0.0), 2)
            except Exception:
                d['expected_amount'] = 0.0
            try:
                d['actual_cash'] = round(float(d.get('actual_cash') or 0.0), 2)
            except Exception:
                d['actual_cash'] = 0.0
            try:
                d['variance'] = round(float(d.get('variance') or 0.0), 2)
            except Exception:
                d['variance'] = round(float(d.get('actual_cash') or 0.0) - float(d.get('expected_amount') or 0.0), 2)
            d['variance_status'] = (d.get('variance_status') or self._dayclose_variance_status(d.get('variance'))).strip() or 'Balanced'
            d['variance_workflow_status'] = self._dayclose_norm_workflow(
                d.get('variance_workflow_status'),
                variance=d.get('variance'),
                is_closed=bool(int(d.get('is_closed') or 0)),
            )
            out.append(d)
        return out




    # Areas (master list)



    def ensure_area_exists(self, name):
        """Insert area into master table if not present."""
        nm = (name or "").strip()
        if not nm:
            return False
        cur = self.conn.cursor()
        try:
            cur.execute("INSERT OR IGNORE INTO areas(name, created_at) VALUES (?, datetime('now'))", (nm,))
            self.conn.commit()
            return True
        except Exception:
            return False

    def add_area(self, name):
        """Add a new area. Returns True if inserted or already exists."""
        return self.ensure_area_exists(name)



    def rename_area(self, old_name, new_name):
        """Rename an area and update all clients that use it (all loan types). Logs client history."""
        old_nm = (old_name or "").strip()
        new_nm = (new_name or "").strip()
        if not old_nm or not new_nm:
            return False
        cur = self.conn.cursor()
        try:
            # Capture affected clients before update (for audit)
            affected = []
            try:
                affected = cur.execute(
                    "SELECT * FROM clients WHERE TRIM(IFNULL(area,'')) = ?",
                    (old_nm,)
                ).fetchall()
            except Exception:
                affected = []
            old_rows = [dict(r) for r in affected] if affected else []

            # Ensure target exists
            cur.execute("INSERT OR IGNORE INTO areas(name, created_at) VALUES (?, datetime('now'))", (new_nm,))
            # Update clients
            cur.execute("UPDATE clients SET area=? WHERE TRIM(IFNULL(area,'')) = ?", (new_nm, old_nm))
            # Remove old area row if different
            if old_nm != new_nm:
                cur.execute("DELETE FROM areas WHERE name = ?", (old_nm,))
            self.conn.commit()

            # Audit log per client
            for r in old_rows:
                try:
                    uid = (r.get("client_uid") or "").strip()
                    if not uid:
                        continue
                    new_row = self.get_client_by_uid(uid) or {}
                    self._log_client_history(uid, 'UPDATE', old_row=r, new_row=new_row, source='areas:rename', note=f"area {old_nm} -> {new_nm}")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0156', 'suppressed exception excpass_0156', __spina_exc)
                    pass

            return True
        except Exception:
            return False



    def delete_area(self, name, clear_clients=False):
        """Delete an area. If clear_clients True, clear that area from all clients (logs history)."""
        nm = (name or "").strip()
        if not nm:
            return False
        cur = self.conn.cursor()
        try:
            old_rows = []
            if clear_clients:
                try:
                    affected = cur.execute(
                        "SELECT * FROM clients WHERE TRIM(IFNULL(area,'')) = ?",
                        (nm,)
                    ).fetchall()
                    old_rows = [dict(r) for r in affected] if affected else []
                except Exception:
                    old_rows = []
                cur.execute("UPDATE clients SET area='' WHERE TRIM(IFNULL(area,'')) = ?", (nm,))

            cur.execute("DELETE FROM areas WHERE name = ?", (nm,))
            self.conn.commit()

            if clear_clients and old_rows:
                for r in old_rows:
                    try:
                        uid = (r.get("client_uid") or "").strip()
                        if not uid:
                            continue
                        new_row = self.get_client_by_uid(uid) or {}
                        self._log_client_history(uid, 'UPDATE', old_row=r, new_row=new_row, source='areas:delete', note=f"area cleared (deleted {nm})")
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0157', 'suppressed exception excpass_0157', __spina_exc)
                        pass

            return True
        except Exception:
            return False



    def add_or_update_transaction(self, name, date_s, payment, description="", loan_type=None, source="databank"):
        """Insert or update a transaction (Data Bank) row.

        Key: prefer (client_uid, loan_type, date); fallback to legacy (name, loan_type, date)

        - Populates `client_uid` when possible so linked profiles can see the same Data Bank rows.
        - Writes an append-only audit row into `transaction_history`.
        """
        cur = self.conn.cursor()
        now = datetime.now().isoformat(sep=' ', timespec='seconds')
        lt = self._effective_lt(loan_type)
        nm = (name or "").strip()

        if self.is_databank_day_closed(date_s, loan_type=lt):
            raise ValueError(f"{date_s} is already closed for the combined Data Bank day (Regular + 7x7). Reopen it with a password before changing Data Bank entries.")

        # Resolve client_uid for this name/type (best-effort)
        client_uid = None
        try:
            client_uid = self.get_client_uid(nm, loan_type=lt)
        except Exception:
            client_uid = None

        # Stable-id path: prevents rename drift and duplicate same-day rows after a rename.
        if client_uid:
            return self.add_or_update_transaction_by_uid(
                client_uid,
                date_s,
                payment,
                description=description,
                loan_type=lt,
                source=source,
            )

        # Fetch old row for audit
        old_row = None
        try:
            r0 = cur.execute(
                "SELECT * FROM transactions WHERE name=? AND loan_type=? AND date=?",
                (nm, lt, date_s)
            ).fetchone()
            if r0:
                old_row = dict(r0)
        except Exception:
            old_row = None

        # Upsert
        cur.execute("SELECT id FROM transactions WHERE name = ? AND loan_type = ? AND date = ?", (nm, lt, date_s))
        r = cur.fetchone()
        if r:
            try:
                rid = r["id"] if isinstance(r, sqlite3.Row) else r[0]
            except Exception:
                rid = r[0]
            # Prefer updating client_uid too (if column exists)
            try:
                cur.execute(
                    "UPDATE transactions SET client_uid=?, payment=?, description=?, created_at=? WHERE id=?",
                    (client_uid, float(payment or 0), description, now, rid)
                )
            except Exception:
                cur.execute(
                    "UPDATE transactions SET payment=?, description=?, created_at=? WHERE id=?",
                    (float(payment or 0), description, now, rid)
                )
        else:
            try:
                cur.execute(
                    "INSERT INTO transactions (client_uid, name, loan_type, date, payment, description, created_at) VALUES (?,?,?,?,?,?,?)",
                    (client_uid, nm, lt, date_s, float(payment or 0), description, now)
                )
            except Exception:
                cur.execute(
                    "INSERT INTO transactions (name, loan_type, date, payment, description, created_at) VALUES (?,?,?,?,?,?)",
                    (nm, lt, date_s, float(payment or 0), description, now)
                )

        self.conn.commit()

        # Fetch new row and audit
        new_row = None
        try:
            r1 = cur.execute(
                "SELECT * FROM transactions WHERE name=? AND loan_type=? AND date=? ORDER BY id DESC LIMIT 1",
                (nm, lt, date_s)
            ).fetchone()
            if r1:
                new_row = dict(r1)
        except Exception:
            new_row = None

        try:
            self._log_transaction_history(
                (client_uid or (new_row or {}).get("client_uid")),
                "TX_UPDATE" if old_row else "TX_ADD",
                old_row=old_row,
                new_row=new_row,
                source=(source or "databank"),
            )
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0158', 'suppressed exception excpass_0158', __spina_exc)
            pass

    def delete_transaction(self, name, date_s, loan_type=None, source="databank"):
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        nm = (name or "").strip()

        if self.is_databank_day_closed(date_s, loan_type=lt):
            raise ValueError(f"{date_s} is already closed for the combined Data Bank day (Regular + 7x7). Reopen it with a password before deleting Data Bank entries.")

        cuid = None
        try:
            cuid = self.get_client_uid(nm, loan_type=lt)
        except Exception:
            cuid = None

        old_row = None
        try:
            if cuid:
                r0 = cur.execute(
                    "SELECT * FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=? ORDER BY id DESC LIMIT 1",
                    (cuid, lt, date_s)
                ).fetchone()
            else:
                r0 = cur.execute(
                    "SELECT * FROM transactions WHERE name=? AND loan_type=? AND date=?",
                    (nm, lt, date_s)
                ).fetchone()
            if r0:
                old_row = dict(r0)
        except Exception:
            old_row = None

        if cuid:
            cur.execute(
                "DELETE FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=?",
                (cuid, lt, date_s)
            )
        else:
            cur.execute("DELETE FROM transactions WHERE name = ? AND loan_type = ? AND date = ?", (nm, lt, date_s))
        self.conn.commit()

        try:
            if old_row and not cuid:
                cuid = (old_row.get("client_uid") or "").strip() or None
            if not cuid:
                cuid = self.get_client_uid(nm, loan_type=lt)
            self._log_transaction_history(
                cuid,
                "TX_DELETE",
                old_row=old_row,
                new_row=None,
                source=(source or "databank"),
            )
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0159', 'suppressed exception excpass_0159', __spina_exc)
            pass


    def delete_transactions_for_day(self, date_s, changed_by='', source="databank:delete_day", reset_close=True):
        """Delete ALL Data Bank transaction rows for one calendar date.

        Safety behavior:
          - Validates YYYY-MM-DD.
          - Creates a JSON backup in data/day_delete_backups BEFORE deleting.
          - Deletes both Regular and 7x7 transactions for that date.
          - Clears the Data Bank close/collector-close lock rows for that date so the day can be re-imported.
          - Writes append-only audit rows into transaction_history and databank_day_close_history.
        """
        from datetime import datetime as _dt
        import os as _os
        import json as _json

        ds = str(date_s or "").strip()[:10]
        try:
            ds = _dt.strptime(ds, "%Y-%m-%d").strftime("%Y-%m-%d")
        except Exception:
            raise ValueError("Invalid date. Use YYYY-MM-DD.")

        cur = self.conn.cursor()

        # Load rows that will be deleted.
        rows = cur.execute(
            """
            SELECT *
              FROM transactions
             WHERE date(date) = date(?)
             ORDER BY IFNULL(NULLIF(TRIM(loan_type),''),'Regular') COLLATE NOCASE,
                      name COLLATE NOCASE,
                      id
            """,
            (ds,),
        ).fetchall() or []

        old_rows = []
        for r in rows:
            try:
                old_rows.append(dict(r))
            except Exception:
                try:
                    old_rows.append({k: r[k] for k in r.keys()})
                except Exception:
                    old_rows.append({})

        # Also back up close records because they are reset for this day.
        close_rows = []
        collector_rows = []
        try:
            close_rows = [dict(r) for r in (cur.execute(
                "SELECT * FROM databank_day_close WHERE close_date=? ORDER BY id",
                (ds,),
            ).fetchall() or [])]
        except Exception:
            close_rows = []
        try:
            collector_rows = [dict(r) for r in (cur.execute(
                "SELECT * FROM databank_day_collector_close WHERE close_date=? ORDER BY sort_order, id",
                (ds,),
            ).fetchall() or [])]
        except Exception:
            collector_rows = []

        # Import re-run safeguard:
        # The encoder importer keeps a JSON dedupe log. Even though the importer is designed
        # to re-import if the DB row was deleted, clearing entries for this exact date makes
        # Delete Day deterministic: delete 2026-03-18 -> import 2026-03-18 again without
        # stale "already imported" state.
        import_log_path = ""
        import_log_obj = {}
        import_log_removed = {}
        try:
            import_log_path = data_path("encoder_import_log.json")
            if import_log_path and _os.path.exists(import_log_path):
                with open(import_log_path, "r", encoding="utf-8") as f:
                    import_log_obj = _json.load(f) or {}
                if not isinstance(import_log_obj, dict):
                    import_log_obj = {}
        except Exception:
            import_log_obj = {}

        try:
            if isinstance(import_log_obj, dict):
                for _k, _v in list(import_log_obj.items()):
                    _hit = False
                    try:
                        # Current log format stores {"date": "YYYY-MM-DD", ...}
                        if isinstance(_v, dict) and str(_v.get("date") or "").strip()[:10] == ds:
                            _hit = True
                    except Exception:
                        _hit = False
                    try:
                        # Fallback for stable key format: YYYY-MM-DD|loan_type|client_uid
                        if not _hit and str(_k or "").split("|", 1)[0] == ds:
                            _hit = True
                    except Exception:
                        pass
                    if _hit:
                        import_log_removed[str(_k)] = _v
        except Exception:
            import_log_removed = {}

        if not old_rows and not close_rows and not collector_rows and not import_log_removed:
            return {
                "date": ds,
                "deleted": 0,
                "backup_path": "",
                "close_reset": False,
                "import_log_cleared": 0,
                "message": "No transactions, close records, or import-log entries found for that date.",
            }

        # Backup FIRST. If backup fails, abort deletion.
        backup_dir = _os.path.join(DATA_DIR, "day_delete_backups")
        try:
            _os.makedirs(backup_dir, exist_ok=True)
        except Exception:
            pass
        ts = _dt.now().strftime("%Y%m%d_%H%M%S")
        backup_path = _os.path.join(backup_dir, f"delete_day_{ds}_{ts}.json")
        payload = {
            "action": "DELETE_DAY_BACKUP",
            "date": ds,
            "created_at": _dt.now().isoformat(sep=" ", timespec="seconds"),
            "changed_by": str(changed_by or "").strip(),
            "source": str(source or "databank:delete_day"),
            "transactions_count": len(old_rows),
            "transactions_total_payment": round(sum(float((r or {}).get("payment") or 0.0) for r in old_rows), 2),
            "transactions": old_rows,
            "databank_day_close": close_rows,
            "databank_day_collector_close": collector_rows,
            "encoder_import_log_path": import_log_path,
            "encoder_import_log_removed_count": len(import_log_removed),
            "encoder_import_log_removed": import_log_removed,
        }
        try:
            tmp = backup_path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                _json.dump(payload, f, ensure_ascii=False, indent=2, default=str)
            _os.replace(tmp, backup_path)
        except Exception as e:
            raise IOError(f"Backup failed, so nothing was deleted. Error: {e}")

        # Delete in one transaction.
        try:
            cur.execute("DELETE FROM transactions WHERE date(date)=date(?)", (ds,))

            close_reset = False
            if reset_close:
                try:
                    cur.execute("DELETE FROM databank_day_collector_close WHERE close_date=?", (ds,))
                    cur.execute("DELETE FROM databank_day_close WHERE close_date=?", (ds,))
                    close_reset = bool(close_rows or collector_rows)
                except Exception:
                    close_reset = False

            self.conn.commit()
        except Exception:
            try:
                self.conn.rollback()
            except Exception:
                pass
            raise

        # Clear stale encoder import-log entries for this date after the DB delete succeeds.
        import_log_cleared = 0
        try:
            if import_log_removed and isinstance(import_log_obj, dict):
                for _k in list(import_log_removed.keys()):
                    import_log_obj.pop(_k, None)
                if import_log_path:
                    if _write_json_atomic(import_log_path, import_log_obj):
                        import_log_cleared = len(import_log_removed)
                    else:
                        try:
                            _log_exc("delete_day.clear_encoder_import_log", Exception("atomic write failed"))
                        except Exception:
                            pass
        except Exception as e:
            try:
                _log_exc("delete_day.clear_encoder_import_log", e)
            except Exception:
                pass

        # Append audit rows after successful deletion.
        note = f"Delete Day {ds}. Backup: {backup_path}"
        if import_log_cleared:
            note += f" Import-log cleared: {import_log_cleared} entr(y/ies)."
        for old in old_rows:
            try:
                self._log_transaction_history(
                    (old.get("client_uid") or ""),
                    "TX_DELETE_DAY",
                    old_row=old,
                    new_row=None,
                    source=(source or "databank:delete_day"),
                    note=note,
                )
            except Exception:
                pass

        try:
            # Log the reset/clear of day close state in history.
            rec = close_rows[0] if close_rows else {
                "close_date": ds,
                "loan_type": self._databank_day_close_bucket(None),
                "expected_amount": 0.0,
                "actual_cash": 0.0,
                "variance": 0.0,
                "variance_status": "Balanced",
                "variance_workflow_status": "Open",
                "is_closed": 0,
                "note": "",
            }
            self._append_databank_day_close_history(
                ds,
                "delete_day_transactions",
                rec=rec,
                actor=str(changed_by or "").strip(),
                note=note,
                loan_type=None,
                source=(source or "databank:delete_day"),
                payload={
                    "backup_path": backup_path,
                    "deleted_transactions": len(old_rows),
                    "deleted_close_records": len(close_rows),
                    "deleted_collector_close_records": len(collector_rows),
                    "encoder_import_log_removed": len(import_log_removed),
                    "encoder_import_log_cleared": import_log_cleared,
                },
            )
            self.conn.commit()
        except Exception:
            pass

        return {
            "date": ds,
            "deleted": len(old_rows),
            "backup_path": backup_path,
            "close_reset": bool(close_rows or collector_rows),
            "import_log_cleared": import_log_cleared,
            "message": f"Deleted {len(old_rows)} transaction row(s) for {ds}.",
        }


    def get_transaction(self, name, date_s, loan_type=None):
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        nm = (name or '').strip()
        try:
            uid = self.get_client_uid(nm, loan_type=lt)
        except Exception:
            uid = None
        if uid:
            cur.execute(
                "SELECT * FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date = ? ORDER BY id DESC LIMIT 1",
                (uid, lt, date_s)
            )
        else:
            cur.execute("SELECT * FROM transactions WHERE name = ? AND loan_type = ? AND date = ?", (nm, lt, date_s))
        return cur.fetchone()




    def get_transaction_by_uid(self, client_uid, date_s, loan_type=None):
        """Fetch a transaction by (client_uid, loan_type, date)."""
        uid = (client_uid or "").strip()
        if not uid:
            return None
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        try:
            cur.execute(
                "SELECT * FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=?",
                (uid, lt, date_s),
            )
            return cur.fetchone()
        except Exception:
            # Fallback: some old DBs may not have client_uid populated
            return None

    def add_or_update_transaction_by_uid(self, client_uid, date_s, payment, description="", loan_type=None, source="databank"):
        """Insert or update a transaction using client_uid as the stable key.

        Key: (client_uid, loan_type, date)

        - Automatically pulls the current client name from clients table.
        - Updates the stored `name` in transactions if the client was renamed.
        - Writes append-only audit rows into transaction_history.
        """
        uid = (client_uid or "").strip()
        if not uid:
            # fallback to name-based if caller passes no uid
            return self.add_or_update_transaction("", date_s, payment, description=description, loan_type=loan_type, source=source)

        cur = self.conn.cursor()
        now = datetime.now().isoformat(sep=' ', timespec='seconds')

        # Resolve current client row/name
        row = None
        try:
            row = self.get_client_by_uid(uid) or None
        except Exception:
            row = None

        nm = ""
        lt_row = None
        try:
            if isinstance(row, dict):
                nm = (row.get("name") or "").strip()
                lt_row = (row.get("loan_type") or "").strip()
        except Exception:
            nm = ""
            lt_row = None

        # Determine effective loan_type
        lt = self._effective_lt(loan_type or lt_row or "Regular")

        if self.is_databank_day_closed(date_s, loan_type=lt):
            raise ValueError(f"{date_s} is already closed for the combined Data Bank day (Regular + 7x7). Reopen it with a password before changing Data Bank entries.")

        # Fetch old row for audit
        old_row = None
        try:
            r0 = cur.execute(
                "SELECT * FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=?",
                (uid, lt, date_s),
            ).fetchone()
            if r0:
                old_row = dict(r0)
        except Exception:
            old_row = None

        # Upsert by client_uid
        try:
            rid_row = cur.execute(
                "SELECT id FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=?",
                (uid, lt, date_s),
            ).fetchone()
        except Exception:
            rid_row = None

        if rid_row:
            try:
                rid = rid_row["id"] if isinstance(rid_row, sqlite3.Row) else rid_row[0]
            except Exception:
                rid = rid_row[0]
            # Update payment/desc and keep name in sync
            try:
                cur.execute(
                    "UPDATE transactions SET name=?, loan_type=?, payment=?, description=?, created_at=? WHERE id=?",
                    (nm, lt, float(payment or 0), description, now, rid),
                )
            except Exception:
                # minimal fallback
                cur.execute(
                    "UPDATE transactions SET payment=?, description=?, created_at=? WHERE id=?",
                    (float(payment or 0), description, now, rid),
                )
        else:
            try:
                cur.execute(
                    "INSERT INTO transactions (client_uid, name, loan_type, date, payment, description, created_at) VALUES (?,?,?,?,?,?,?)",
                    (uid, nm, lt, date_s, float(payment or 0), description, now),
                )
            except Exception:
                # fallback to legacy insert
                cur.execute(
                    "INSERT INTO transactions (name, loan_type, date, payment, description, created_at) VALUES (?,?,?,?,?,?)",
                    (nm, lt, date_s, float(payment or 0), description, now),
                )

        self.conn.commit()

        # Fetch new row and audit
        new_row = None
        try:
            r1 = cur.execute(
                "SELECT * FROM transactions WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') AND date=? ORDER BY id DESC LIMIT 1",
                (uid, lt, date_s),
            ).fetchone()
            if r1:
                new_row = dict(r1)
        except Exception:
            new_row = None

        try:
            self._log_transaction_history(
                uid,
                "TX_UPDATE" if old_row else "TX_ADD",
                old_row=old_row,
                new_row=new_row,
                source=(source or "databank"),
            )
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_tx_uid_audit', 'suppressed exception excpass_tx_uid_audit', __spina_exc)
            pass




    def import_missing_clients_from_transactions(self):
        """Ensure every (name, loan_type) in transactions has a matching row in clients.

        Older versions only tracked names (no loan_type). This version is multi-loan-type safe.
        For 7x7 loans, we default interest_rate to 0.0.
        """
        cur = self.conn.cursor()

        # Collect distinct (name, loan_type) from transactions
        tx = set()
        try:
            cur.execute("SELECT DISTINCT name, loan_type FROM transactions")
            for r in (cur.fetchall() or []):
                try:
                    nm = (r[0] or "").strip()
                    lt = self._norm_lt(r[1] if len(r) > 1 else None)
                    if nm:
                        tx.add((nm, lt))
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0160', 'suppressed exception excpass_0160', __spina_exc)
                    pass
        except Exception:
            # Legacy fallback (no loan_type column)
            try:
                cur.execute("SELECT DISTINCT name FROM transactions")
                for (nm,) in (cur.fetchall() or []):
                    nm = (nm or "").strip()
                    if nm:
                        tx.add((nm, self._effective_lt(None)))
            except Exception:
                return 0

        # Collect existing (name, loan_type) from clients
        cl = set()
        try:
            cur.execute("SELECT name, loan_type FROM clients")
            for r in (cur.fetchall() or []):
                try:
                    nm = (r[0] or "").strip()
                    lt = self._norm_lt(r[1] if len(r) > 1 else None)
                    if nm:
                        cl.add((nm, lt))
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0161', 'suppressed exception excpass_0161', __spina_exc)
                    pass
        except Exception:
            try:
                cur.execute("SELECT name FROM clients")
                for (nm,) in (cur.fetchall() or []):
                    nm = (nm or "").strip()
                    if nm:
                        cl.add((nm, self._effective_lt(None)))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0162', 'suppressed exception excpass_0162', __spina_exc)
                pass

        miss = tx - cl
        if not miss:
            return 0

        today_s = date.today().isoformat()
        inserted = 0

        for nm, lt in miss:
            try:
                lt_norm = self._norm_lt(lt)
                is_7x7 = (lt_norm.lower().replace(" ", "") == "7x7")
                ir = 0.0 if is_7x7 else 0.20
                cur.execute(
                    "INSERT INTO clients (name, created_at, loan_type, interest_rate) VALUES (?,?,?,?)",
                    (nm, today_s, lt_norm, ir),
                )
                inserted += 1
            except Exception:
                # Try a minimal insert if schema differs
                try:
                    cur.execute(
                        "INSERT INTO clients (name, created_at, loan_type) VALUES (?,?,?)",
                        (nm, today_s, self._norm_lt(lt)),
                    )
                    inserted += 1
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0163', 'suppressed exception excpass_0163', __spina_exc)
                    pass

        self.conn.commit()
        return inserted

