    def _remove_role_overlays(self):
        for attr in ('_role_overlay_data', '_role_overlay_reports', '_role_overlay_collectors'):
            ov = getattr(self, attr, None)
            try:
                if ov is not None:
                    ov.destroy()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0192', 'suppressed exception excpass_0192', __spina_exc)
                pass
            try:
                setattr(self, attr, None)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0193', 'suppressed exception excpass_0193', __spina_exc)
                pass


    def _restore_main_tabs(self):
        specs = (
            (getattr(self, 'tab_data', None), 'Data Bank'),
            (getattr(self, 'tab_reports', None), 'Reports'),
            (getattr(self, 'tab_clients', None), 'Clients'),
            (getattr(self, 'tab_collectors', None), "Collector's Route"),
        )
        for child, title in specs:
            if child is None:
                continue
            try:
                self.nb.add(child, text=title)
            except Exception:
                try:
                    self.nb.tab(child, text=title)
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_restore_main_tabs', 'suppressed exception excpass_restore_main_tabs', __spina_exc)
                    pass

    def _make_import_only_overlay(self, parent, title: str, import_cmd):
        """Overlay that blocks tab interaction, leaving only an Import button."""
        from tkinter import ttk
        ov = ttk.Frame(parent)
        ov.place(relx=0, rely=0, relwidth=1, relheight=1)
        try:
            ov.lift()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0194', 'suppressed exception excpass_0194', __spina_exc)
            pass

        card = ttk.Frame(ov, padding=18)
        card.place(relx=0.5, rely=0.18, anchor='n')

        ttk.Label(card, text=title, font=('TkDefaultFont', 12, 'bold')).pack(pady=(0, 8))
        ttk.Label(card, text='This account can only import files.', justify='center').pack(pady=(0, 12))
        ttk.Button(card, text='Import…', command=import_cmd).pack()

        return ov

    def _make_close_only_overlay(self, parent, title: str, open_cmd):
        """Overlay that blocks tab interaction, leaving only Daily Close / Variance access."""
        from tkinter import ttk
        ov = ttk.Frame(parent)
